-- FutureFinance MySQL 8.0 schema: normalized to 3NF
CREATE DATABASE IF NOT EXISTS futurefinance; USE futurefinance;
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE financial_profiles (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL UNIQUE,age TINYINT UNSIGNED,monthly_income DECIMAL(14,2) NOT NULL DEFAULT 0 CHECK(monthly_income>=0),savings DECIMAL(14,2) NOT NULL DEFAULT 0 CHECK(savings>=0),risk_tolerance ENUM('low','moderate','high') DEFAULT 'moderate',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE income (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,source ENUM('Salary','Freelance','Business','Interest','Other') NOT NULL,amount DECIMAL(14,2) NOT NULL CHECK(amount>0),received_on DATE NOT NULL,description TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX ix_income_user_date(user_id,received_on));
CREATE TABLE expenses (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,category ENUM('Food','Transportation','Education','Entertainment','Shopping','Healthcare','Rent','Utilities','Other') NOT NULL,amount DECIMAL(14,2) NOT NULL CHECK(amount>0),spent_on DATE NOT NULL,description TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX ix_expense_user_date(user_id,spent_on),INDEX ix_expense_category(category));
CREATE TABLE investments (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,name VARCHAR(120) NOT NULL,investment_type ENUM('Stocks','Mutual Funds','Fixed Deposits','Bonds','Gold','ETFs') NOT NULL,amount_invested DECIMAL(14,2) NOT NULL CHECK(amount_invested>0),current_value DECIMAL(14,2) NOT NULL CHECK(current_value>=0),purchase_date DATE NOT NULL,expected_return DECIMAL(5,2) DEFAULT 10,risk_level ENUM('low','medium','high') DEFAULT 'medium',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX ix_investment_user_type(user_id,investment_type));
CREATE TABLE financial_goals (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,name VARCHAR(120) NOT NULL,target_amount DECIMAL(14,2) NOT NULL CHECK(target_amount>0),current_amount DECIMAL(14,2) NOT NULL DEFAULT 0 CHECK(current_amount>=0),target_date DATE NOT NULL,priority ENUM('low','medium','high') DEFAULT 'medium',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE loans (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,lender VARCHAR(120) NOT NULL,outstanding_amount DECIMAL(14,2) NOT NULL CHECK(outstanding_amount>=0),monthly_emi DECIMAL(14,2) NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE scenarios (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,name VARCHAR(120) NOT NULL,income_change_pct DECIMAL(6,2) DEFAULT 0,expense_change_pct DECIMAL(6,2) DEFAULT 0,contribution_change DECIMAL(14,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE simulation_runs (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,initial_amount DECIMAL(14,2) NOT NULL,monthly_contribution DECIMAL(14,2) NOT NULL,annual_return DECIMAL(6,2) NOT NULL,volatility DECIMAL(6,2) NOT NULL,years INT NOT NULL,simulations INT NOT NULL,goal_target DECIMAL(14,2),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,action VARCHAR(20) NOT NULL,table_name VARCHAR(64) NOT NULL,record_id BIGINT NOT NULL,details JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX ix_audit_user_time(user_id,created_at));
